// Created: 2026-08-21

// Invokes the REAL middleware to pin the three contracts the Is Agentic audit
// scored Partial, because all three are middleware behavior and none of them is
// observable from a unit test of the helpers alone:
//
//   1. agent-friendly 404s, a real 404 whose body names the recovery hops, in
//      the media type the client asked for (audit: "include a short markdown
//      body ... so agents can recover").
//   2. rate-limit headers on EVERY API response, including the prerendered
//      discovery surfaces a `revalidate = false` handler cannot decorate
//      (audit: "documented in OpenAPI spec, but not observed on a live response").
//   3. Markdown twins for the named pages, so "append .md to a page URL" is true
//      outside /docs (audit: "searched for 'yonyon' developer resources but
//      found nothing relevant").

import { NextRequest } from "next/server";
import { beforeEach, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/analytics-server", () => ({
	reportServerEvent: vi.fn(),
	reportServerEvents: vi.fn(),
}));

import { middleware } from "@/middleware";
import { RATE_LIMIT } from "@/lib/rate-limit";

const ORIGIN = "https://orchestkit.yonyon.ai";

function req(path: string, accept = "*/*", ip = "203.0.113.1") {
	return new NextRequest(`${ORIGIN}${path}`, {
		headers: { accept, "x-real-ip": ip, "user-agent": "curl/8.7.1" },
	});
}

let ipCounter = 0;
/** A fresh IP per test, so one test's window never leaks into another's. */
function freshIp() {
	ipCounter += 1;
	return `198.51.100.${ipCounter}`;
}

describe("agent-friendly 404s", () => {
	it("an unknown path is a real 404, never a 200 shell", async () => {
		const res = middleware(req("/some-path-that-does-not-exist"));
		expect(res?.status).toBe(404);
	});

	it("Accept: text/markdown gets a Markdown body with recovery links", async () => {
		const res = middleware(
			req("/some-path-that-does-not-exist", "text/markdown"),
		) as Response;
		expect(res.status).toBe(404);
		expect(res.headers.get("content-type")).toContain("text/markdown");
		const body = await res.text();
		expect(body).toContain("# 404");
		expect(body).toContain("[llms.txt](/llms.txt)");
		expect(body).toContain("[Sitemap](/sitemap.xml)");
		expect(body).toContain("/some-path-that-does-not-exist");
	});

	it("a `.md` suffix on an unknown page also yields Markdown, not HTML", async () => {
		// The regression this pins: /developers.md returned `404 text/html` in
		// production on 2026-08-21 while the docs told agents to append `.md`.
		const res = middleware(req("/not-a-real-page.md")) as Response;
		expect(res.status).toBe(404);
		expect(res.headers.get("content-type")).toContain("text/markdown");
	});

	it("?mode=agent yields Markdown too", async () => {
		const res = middleware(
			new NextRequest(`${ORIGIN}/nope?mode=agent`, {
				headers: { accept: "*/*", "x-real-ip": freshIp() },
			}),
		) as Response;
		expect(res.status).toBe(404);
		expect(res.headers.get("content-type")).toContain("text/markdown");
	});

	it("a JSON client gets RFC 9457 with links + markdown extension members", async () => {
		const res = middleware(
			req("/checkout_sessions", "application/json"),
		) as Response;
		expect(res.status).toBe(404);
		expect(res.headers.get("content-type")).toContain("application/json");
		const body = (await res.json()) as {
			status: number;
			instance: string;
			links: { href: string }[];
			markdown: string;
		};
		expect(body.status).toBe(404);
		expect(body.instance).toBe("/checkout_sessions");
		expect(body.links.some((l) => l.href.endsWith("/llms.txt"))).toBe(true);
		expect(body.markdown).toContain("llms.txt");
	});

	it("a browser still falls through to the HTML not-found page", async () => {
		const res = middleware(req("/checkout_sessions", "text/html"));
		// NextResponse.next(), the request is passed through to Next, which
		// renders app/not-found.tsx. No synthesized body, so no content-type here.
		expect(res?.status).toBe(200);
		expect(res?.headers.get("content-type")).toBeNull();
	});
});

describe("rate-limit headers on every metered surface", () => {
	it.each([
		"/api/health",
		"/openapi.json",
		"/llms.txt",
		"/.well-known/api-catalog",
		"/.well-known/agent-card.json",
		"/api/mcp",
	])("%s carries RateLimit-* headers", (path) => {
		const res = middleware(req(path, "application/json", freshIp()));
		expect(res?.headers.get("ratelimit-limit")).toBe(String(RATE_LIMIT));
		expect(res?.headers.get("ratelimit-policy")).toBe(`${RATE_LIMIT};w=60`);
		expect(res?.headers.get("ratelimit-remaining")).toBe(String(RATE_LIMIT - 1));
		expect(res?.headers.get("ratelimit-reset")).not.toBeNull();
	});

	it("does not decorate an HTML page view", () => {
		// Metering page views would let ordinary browsing trip an API abuse brake.
		const res = middleware(req("/pricing", "text/html", freshIp()));
		expect(res?.headers.get("ratelimit-limit")).toBeNull();
	});

	it("does not decorate a self-limiting route (the handler owns that counter)", () => {
		const res = middleware(req("/api/search?query=x", "application/json", freshIp()));
		expect(res?.headers.get("ratelimit-limit")).toBeNull();
	});

	it("a 404 on a metered agent surface still carries the headers", () => {
		// An unknown /.well-known probe is the single highest-volume agent request
		// shape there is (scanners walk the whole registry), and it is exactly the
		// case where a client most needs to know its remaining budget.
		const res = middleware(
			req("/.well-known/oauth-authorization-server", "application/json", freshIp()),
		);
		expect(res?.status).toBe(404);
		expect(res?.headers.get("ratelimit-limit")).toBe(String(RATE_LIMIT));
	});

	it("an unknown NON-API path is not metered", () => {
		// Deliberate: the counter is keyed by route, so metering arbitrary unknown
		// paths would mint one window per garbage URL, an unbounded key space and
		// no brake at all, since each probe would see a fresh quota. Such a path
		// still gets a real 404 with the recovery body; it just carries no quota.
		const res = middleware(req("/nope.json", "application/json", freshIp()));
		expect(res?.status).toBe(404);
		expect(res?.headers.get("ratelimit-limit")).toBeNull();
	});

	it("past the ceiling it returns 429 with Retry-After and a problem body", async () => {
		const ip = freshIp();
		for (let i = 0; i < RATE_LIMIT; i++) {
			middleware(req("/api/health", "application/json", ip));
		}
		const res = middleware(req("/api/health", "application/json", ip)) as Response;
		expect(res.status).toBe(429);
		expect(res.headers.get("retry-after")).not.toBeNull();
		expect(res.headers.get("ratelimit-remaining")).toBe("0");
		const body = (await res.json()) as { status: number; detail: string };
		expect(body.status).toBe(429);
		expect(body.detail).toContain("/api-policy");
	});
});

describe("Markdown twins for the named pages", () => {
	it.each([
		["/developers.md", "/api/page-md/developers"],
		["/yonyon.md", "/api/page-md/yonyon"],
	])("%s rewrites to %s", (from, to) => {
		const res = middleware(req(from, "*/*", freshIp()));
		expect(res?.headers.get("x-middleware-rewrite")).toContain(to);
	});

	it("Accept: text/markdown on the bare page rewrites the same way", () => {
		const res = middleware(req("/developers", "text/markdown", freshIp()));
		expect(res?.headers.get("x-middleware-rewrite")).toContain(
			"/api/page-md/developers",
		);
	});

	it("does not hijack a page that owns a real .md route", () => {
		// /api-policy.md and /pricing.md are their own handlers; a twin rewrite
		// here would shadow them.
		for (const p of ["/api-policy.md", "/pricing.md", "/auth.md"]) {
			const res = middleware(req(p, "*/*", freshIp()));
			expect(res?.headers.get("x-middleware-rewrite")).toBeNull();
			expect(res?.status).toBe(200);
		}
	});

	it("still rewrites /docs/*.md to the docs Markdown route", () => {
		const res = middleware(req("/docs/foundations/overview.md", "*/*", freshIp()));
		expect(res?.headers.get("x-middleware-rewrite")).toContain(
			"/api/md/foundations/overview",
		);
	});
});
